using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;

            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        public static SchoolContext CreateWithSeedData(string? dbName = null)
        {
            var context = Create(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            // Students
            var students = new[]
            {
                new Student { FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Parse("2020-09-01") },
                new Student { FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Parse("2021-09-01") },
                new Student { FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = DateTime.Parse("2022-09-01") },
            };
            context.Students.AddRange(students);
            context.SaveChanges();

            // Instructors
            var instructors = new[]
            {
                new Instructor { FirstMidName = "Kim", LastName = "Abercrombie", HireDate = DateTime.Parse("1995-03-11"), CourseAssignments = new List<CourseAssignment>() },
                new Instructor { FirstMidName = "Fadi", LastName = "Fakhouri", HireDate = DateTime.Parse("2002-07-06"), CourseAssignments = new List<CourseAssignment>() },
            };
            context.Instructors.AddRange(instructors);
            context.SaveChanges();

            // Departments
            var departments = new[]
            {
                new Department { Name = "English", Budget = 350000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = instructors[0].ID },
                new Department { Name = "Mathematics", Budget = 100000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = instructors[1].ID },
            };
            context.Departments.AddRange(departments);
            context.SaveChanges();

            // Courses
            var courses = new[]
            {
                new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = departments[0].DepartmentID },
                new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = departments[1].DepartmentID },
                new Course { CourseID = 2021, Title = "Composition", Credits = 3, DepartmentID = departments[0].DepartmentID },
            };
            context.Courses.AddRange(courses);
            context.SaveChanges();

            // CourseAssignments
            context.CourseAssignments.Add(new CourseAssignment { CourseID = 1050, InstructorID = instructors[0].ID });
            context.CourseAssignments.Add(new CourseAssignment { CourseID = 4022, InstructorID = instructors[1].ID });
            context.SaveChanges();

            // Enrollments
            context.Enrollments.Add(new Enrollment { StudentID = students[0].ID, CourseID = 1050, Grade = Grade.A });
            context.Enrollments.Add(new Enrollment { StudentID = students[1].ID, CourseID = 4022, Grade = Grade.B });
            context.SaveChanges();

            // OfficeAssignment
            context.OfficeAssignments.Add(new OfficeAssignment { InstructorID = instructors[1].ID, Location = "Smith 17" });
            context.SaveChanges();
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain any leftover notifications from the static queue (other tests may have added)
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesNotification()
        {
            // Act
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("created", notification.Message);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
        {
            // Act
            _sut.SendNotification("Course", "42", EntityOperation.UPDATE, "Teacher");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("updated", notification.Message);
            Assert.Equal("Teacher", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithNullUserName_DefaultsToSystem()
        {
            // Act
            _sut.SendNotification("Department", "5", EntityOperation.DELETE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_DeleteOperation_ContainsDeletedMessage()
        {
            // Act
            _sut.SendNotification("Student", "3", "Jane Smith", EntityOperation.DELETE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("deleted", notification.Message);
            Assert.Contains("Jane Smith", notification.Message);
        }

        [Fact]
        public void SendNotification_CreateOperation_ContainsNewPrefix()
        {
            // Act
            _sut.SendNotification("Instructor", "7", "Dr. Brown", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.StartsWith("New", notification.Message);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtTimestamp()
        {
            // Arrange
            var before = DateTime.Now.AddSeconds(-1);

            // Act
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.True(notification.CreatedAt >= before);
            Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
        }

        [Fact]
        public void ReceiveNotification_WhenQueueEmpty_ReturnsNull()
        {
            // Drain existing
            while (_sut.ReceiveNotification() != null) { }

            // Act
            var result = _sut.ReceiveNotification();

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_ReturnsFifoOrder()
        {
            // Arrange
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", EntityOperation.DELETE);

            // Act & Assert
            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();
            var third = _sut.ReceiveNotification();

            Assert.Equal("A", first!.EntityType);
            Assert.Equal("B", second!.EntityType);
            Assert.Equal("C", third!.EntityType);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // This is a no-op in the in-memory implementation
            var ex = Record.Exception(() => _sut.MarkAsRead(42));
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_MultipleNotifications_AllRetrievable()
        {
            // Arrange & Act
            for (int i = 0; i < 5; i++)
            {
                _sut.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            // Assert
            var count = 0;
            while (_sut.ReceiveNotification() != null) count++;
            Assert.Equal(5, count);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var ex = Record.Exception(() => service.Dispose());
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_UpdateOperation_ContainsUpdatedMessage()
        {
            // Act
            _sut.SendNotification("Department", "10", "Engineering", EntityOperation.UPDATE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("updated", notification.Message);
            Assert.Contains("Engineering", notification.Message);
            Assert.Equal("UPDATE", notification.Operation);
        }
    }
}

