namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
            _controller.TempData = new TempDataDictionary(new DefaultHttpContext(), new SessionStateTempDataProvider(new SessionStateTempDataSerializer()));
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_ReturnsJsonResult()
        {
            var result = _controller.GetNotifications();

            Assert.IsType<JsonResult>(result);
        }

        [Fact]
        public void GetNotifications_WithNoNotifications_ReturnsSuccessWithEmptyList()
        {
            // Drain all notifications
            while (_controller.GetNotifications() is JsonResult jr)
            {
                var value = jr.Value;
                // After draining, break
                var countProp = value?.GetType().GetProperty("count");
                if (countProp != null && (int)countProp.GetValue(value)! == 0) break;
            }

            var result = _controller.GetNotifications();

            Assert.IsType<JsonResult>(result);
            var resultValue = result.Value;
            Assert.NotNull(resultValue);
            var successProp = resultValue!.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(resultValue)!);
            var countPropFinal = resultValue.GetType().GetProperty("count");
            Assert.Equal(0, (int)countPropFinal!.GetValue(resultValue)!);
        }

        [Fact]
        public void MarkAsRead_ReturnsJsonResult()
        {
            var result = _controller.MarkAsRead(1);

            Assert.IsType<JsonResult>(result);
            var resultValue = result.Value;
            Assert.NotNull(resultValue);
            var successProp = resultValue!.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(resultValue)!);
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _controller.Index();
            Assert.IsType<ViewResult>(result);
        }
    }
