using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Constructor_SetsPageIndex()
        {
            var items = new List<int> { 1, 2, 3 };
            var sut = new PaginatedList<int>(items, 10, 2, 3);

            Assert.Equal(2, sut.PageIndex);
        }

        [Fact]
        public void Constructor_CalculatesTotalPages()
        {
            var items = new List<int> { 1, 2, 3 };
            var sut = new PaginatedList<int>(items, 10, 1, 3);

            Assert.Equal(4, sut.TotalPages); // ceil(10/3) = 4
        }

        [Fact]
        public void Constructor_AddsItemsToList()
        {
            var items = new List<int> { 1, 2, 3 };
            var sut = new PaginatedList<int>(items, 10, 1, 3);

            Assert.Equal(3, sut.Count);
            Assert.Contains(1, sut);
            Assert.Contains(2, sut);
            Assert.Contains(3, sut);
        }

        [Fact]
        public void HasPreviousPage_OnFirstPage_ReturnsFalse()
        {
            var sut = new PaginatedList<int>(new List<int>(), 10, 1, 5);
            Assert.False(sut.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_OnSecondPage_ReturnsTrue()
        {
            var sut = new PaginatedList<int>(new List<int>(), 10, 2, 5);
            Assert.True(sut.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_OnLastPage_ReturnsFalse()
        {
            var sut = new PaginatedList<int>(new List<int>(), 10, 2, 5);
            // TotalPages = ceil(10/5) = 2, PageIndex = 2
            Assert.False(sut.HasNextPage);
        }

        [Fact]
        public void HasNextPage_OnFirstPage_ReturnsTrue()
        {
            var sut = new PaginatedList<int>(new List<int>(), 10, 1, 5);
            // TotalPages = ceil(10/5) = 2, PageIndex = 1
            Assert.True(sut.HasNextPage);
        }

        [Fact]
        public void Create_ReturnsCorrectPageOfItems()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();
            var result = PaginatedList<int>.Create(source, 2, 5);

            Assert.Equal(2, result.PageIndex);
            Assert.Equal(4, result.TotalPages); // ceil(20/5) = 4
            Assert.Equal(5, result.Count);
            Assert.Equal(6, result[0]); // first item on page 2
            Assert.Equal(10, result[4]); // last item on page 2
        }

        [Fact]
        public void Create_FirstPage_ReturnsFirstItems()
        {
            var source = Enumerable.Range(1, 15).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 5);

            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.Equal(5, result.Count);
            Assert.Equal(1, result[0]);
            Assert.Equal(5, result[4]);
        }

        [Fact]
        public void Create_LastPagePartial_ReturnsRemainingItems()
        {
            var source = Enumerable.Range(1, 12).AsQueryable();
            var result = PaginatedList<int>.Create(source, 3, 5);

            Assert.Equal(3, result.PageIndex);
            Assert.Equal(3, result.TotalPages); // ceil(12/5) = 3
            Assert.Equal(2, result.Count); // only 2 items left
            Assert.Equal(11, result[0]);
            Assert.Equal(12, result[1]);
        }

        [Fact]
        public void TotalPages_WithExactDivision_CalculatesCorrectly()
        {
            var sut = new PaginatedList<int>(new List<int>(), 20, 1, 5);
            Assert.Equal(4, sut.TotalPages); // 20/5 = exactly 4
        }

        [Fact]
        public void TotalPages_WithSingleItem_ReturnsOne()
        {
            var sut = new PaginatedList<int>(new List<int> { 1 }, 1, 1, 10);
            Assert.Equal(1, sut.TotalPages);
        }

        [Fact]
        public void HasNextPage_SinglePage_ReturnsFalse()
        {
            var sut = new PaginatedList<int>(new List<int> { 1 }, 1, 1, 10);
            Assert.False(sut.HasNextPage);
        }

        [Fact]
        public void HasPreviousPage_SinglePage_ReturnsFalse()
        {
            var sut = new PaginatedList<int>(new List<int> { 1 }, 1, 1, 10);
            Assert.False(sut.HasPreviousPage);
        }
    }
}

