namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2023-01-01")
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var retrieved = _context.Students.Find(student.ID);
            Assert.NotNull(retrieved);
            Assert.Equal("Test", retrieved!.FirstMidName);
            Assert.Equal("Student", retrieved.LastName);
            Assert.Equal(DateTime.Parse("2023-01-01"), retrieved.EnrollmentDate);
        }

        [Fact]
        public void CanAddAndRetrieveInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Instructor",
                HireDate = DateTime.Parse("2020-06-15"),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var retrieved = _context.Instructors.Find(instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal("Test", retrieved!.FirstMidName);
            Assert.Equal("Instructor", retrieved.LastName);
            Assert.Equal(DateTime.Parse("2020-06-15"), retrieved.HireDate);
        }

        [Fact]
        public void CanAddAndRetrieveCourse()
        {
            var dept = new Department { Name = "TestDept", Budget = 100000, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 7777, Title = "Test Course", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var retrieved = _context.Courses.Find(7777);
            Assert.NotNull(retrieved);
            Assert.Equal("Test Course", retrieved!.Title);
            Assert.Equal(3, retrieved.Credits);
            Assert.Equal(dept.DepartmentID, retrieved.DepartmentID);
        }

        [Fact]
        public void CanAddAndRetrieveDepartment()
        {
            var dept = new Department { Name = "Science", Budget = 250000, StartDate = DateTime.Parse("2023-01-01") };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var retrieved = _context.Departments.Find(dept.DepartmentID);
            Assert.NotNull(retrieved);
            Assert.Equal("Science", retrieved!.Name);
            Assert.Equal(250000, retrieved.Budget);
        }

        [Fact]
        public void CanAddAndRetrieveEnrollment()
        {
            var student = new Student { FirstMidName = "E", LastName = "Student", EnrollmentDate = DateTime.Now };
            _context.Students.Add(student);
            var dept = new Department { Name = "Dept", Budget = 1000, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 8888, Title = "Enrollment Course", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var enrollment = new Enrollment { StudentID = student.ID, CourseID = 8888, Grade = Grade.A };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            var retrieved = _context.Enrollments.First(e => e.CourseID == 8888 && e.StudentID == student.ID);
            Assert.Equal(Grade.A, retrieved.Grade);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            var instructor = new Instructor { FirstMidName = "CA", LastName = "Test", HireDate = DateTime.Now, CourseAssignments = new System.Collections.Generic.List<CourseAssignment>() };
            _context.Instructors.Add(instructor);
            var dept = new Department { Name = "CADept", Budget = 1000, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 6666, Title = "CA Course", Credits = 2, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var ca = new CourseAssignment { CourseID = 6666, InstructorID = instructor.ID };
            _context.CourseAssignments.Add(ca);
            _context.SaveChanges();

            var retrieved = _context.CourseAssignments.Find(6666, instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal(6666, retrieved!.CourseID);
            Assert.Equal(instructor.ID, retrieved.InstructorID);
        }

        [Fact]
        public void OfficeAssignment_LinkedToInstructor()
        {
            var instructor = new Instructor { FirstMidName = "OA", LastName = "Test", HireDate = DateTime.Now, CourseAssignments = new System.Collections.Generic.List<CourseAssignment>() };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var oa = new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 101" };
            _context.OfficeAssignments.Add(oa);
            _context.SaveChanges();

            var retrieved = _context.OfficeAssignments.Find(instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal("Room 101", retrieved!.Location);
        }

        [Fact]
        public void Student_InheritsFromPerson()
        {
            var student = new Student { FirstMidName = "John", LastName = "Doe", EnrollmentDate = DateTime.Now };
            Assert.IsAssignableFrom<Person>(student);
            Assert.Equal("Doe, John", student.FullName);
        }

        [Fact]
        public void Instructor_InheritsFromPerson()
        {
            var instructor = new Instructor { FirstMidName = "Jane", LastName = "Smith", HireDate = DateTime.Now, CourseAssignments = new System.Collections.Generic.List<CourseAssignment>() };
            Assert.IsAssignableFrom<Person>(instructor);
            Assert.Equal("Smith, Jane", instructor.FullName);
        }

        [Fact]
        public void CanAddNotification()
        {
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Student created",
                CreatedAt = DateTime.Now,
                CreatedBy = "System",
                IsRead = false
            };
            _context.Notifications.Add(notification);
            _context.SaveChanges();

            var retrieved = _context.Notifications.Find(notification.Id);
            Assert.NotNull(retrieved);
            Assert.Equal("Student", retrieved!.EntityType);
            Assert.Equal("CREATE", retrieved.Operation);
            Assert.Equal("Student created", retrieved.Message);
            Assert.False(retrieved.IsRead);
        }
    }
}

