+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+using Xunit;
+
+namespace ContosoUniversity.Tests.Services
+{
+    public class NotificationServiceTests : IDisposable
+    {
+        private readonly NotificationService _sut;
+
+        public NotificationServiceTests()
+        {
+            _sut = new NotificationService();
+            // Drain any leftover notifications from the static queue (other tests may have added)
+            while (_sut.ReceiveNotification() != null) { }
+        }
+
+        public void Dispose()
+        {
+            _sut.Dispose();
+        }
+
+        [Fact]
+        public void SendNotification_WithDisplayName_EnqueuesNotification()
+        {
+            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Student", notification.EntityType);
+            Assert.Equal("1", notification.EntityId);
+            Assert.Equal("CREATE", notification.Operation);
+            Assert.Contains("John Doe", notification.Message);
+            Assert.Contains("created", notification.Message);
+            Assert.Equal("Admin", notification.CreatedBy);
+            Assert.False(notification.IsRead);
+        }
+
+        [Fact]
+        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
+        {
+            _sut.SendNotification("Course", "42", EntityOperation.UPDATE, "Teacher");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Course", notification.EntityType);
+            Assert.Equal("42", notification.EntityId);
+            Assert.Contains("ID: 42", notification.Message);
+            Assert.Contains("updated", notification.Message);
+            Assert.Equal("Teacher", notification.CreatedBy);
+        }
+
+        [Fact]
+        public void SendNotification_WithNullUserName_DefaultsToSystem()
+        {
+            _sut.SendNotification("Department", "5", EntityOperation.DELETE);
+
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("System", notification.CreatedBy);
+        }
+
+        [Fact]
+        public void SendNotification_DeleteOperation_ContainsDeletedMessage()
+        {
+            _sut.SendNotification("Student", "3", "Jane Smith", EntityOperation.DELETE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Contains("deleted", notification.Message);
+            Assert.Contains("Jane Smith", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_CreateOperation_ContainsNewPrefix()
+        {
+            _sut.SendNotification("Instructor", "7", "Dr. Brown", EntityOperation.CREATE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.StartsWith("New", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_SetsCreatedAtTimestamp()
+        {
+            var before = DateTime.Now.AddSeconds(-1);
+
+            _sut.SendNotification("Student", "1", EntityOperation.CREATE);
+
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.True(notification.CreatedAt >= before);
+            Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
+        }
+
+        [Fact]
+        public void ReceiveNotification_WhenQueueEmpty_ReturnsNull()
+        {
+            while (_sut.ReceiveNotification() != null) { }
+
+            var result = _sut.ReceiveNotification();
+
+            Assert.Null(result);
+        }
+
