+        {
+            // Drain all notifications first
+            while (true)
+            {
+                var jr = _controller.GetNotifications();
+                var value = jr.Value;
+                var countProp = value?.GetType().GetProperty("count");
+                if (countProp != null && (int)countProp.GetValue(value)! == 0) break;
